export function getPracticeTopics(task: TaskType, level?: PracticeLevel): readonly PracticeTopic[] {
  // File order is not curriculum order. Every task has an authored response
  // construction sequence which is shared by B2, C1 and C2; only the
  // language and independence expected within a part change by level.
  const topicsForTask = PRACTICE_TOPICS.filter((topic) => topic.task === task).sort(
    (left, right) => left.taskPartOrder - right.taskPartOrder,
  );
  if (!level) return topicsForTask;

  // The curriculum taxonomy remains visible to authors at every level; the
  // learner-facing selector only exposes a topic after its complete reviewed
  // six-stage set has been added to the bank for that exact task and level.
  return topicsForTask.filter((topic) => hasCompletePracticePath(task, level, topic.id));
}

/**
 * A part stays in the task blueprint at every level. This predicate controls
 * only whether its fixed, reviewed six-stage path is ready to start.
 */
export function hasCompletePracticePath(task: TaskType, level: PracticeLevel, skill: string): boolean {
  const coveredOrders = new Set(
    PRACTICE_EXERCISES.filter(
      (exercise) => exercise.task === task && exercise.level === level && exercise.skill === skill,
    ).map((exercise) => exercise.sequenceOrder),
  );
  return coveredOrders.size === PRACTICE_EXERCISE_SEQUENCE.length;
}

/**
 * A hint is a reviewed starting move, not a solution. Existing open-writing
 * entries use their first exercise-specific self-check criterion until an
 * editor supplies a separate hint field.
 */
export function getPracticeHint(exercise: PracticeExercise): string | null {
  if (exercise.exerciseType !== "develop" && exercise.exerciseType !== "produce") return null;
  return exercise.hint ?? exercise.selfCheck?.[0] ?? null;
}

export function getPracticeExercises(task: TaskType, level: PracticeLevel, skill: string): readonly PracticeExercise[] {
  return PRACTICE_EXERCISES.filter(
    (exercise) => exercise.task === task && exercise.level === level && exercise.skill === skill,
  ).sort((left, right) => left.sequenceOrder - right.sequenceOrder);
}

export function getPracticeTopic(task: TaskType, skill: string): PracticeTopic | undefined {
  return PRACTICE_TOPICS.find((topic) => topic.task === task && topic.id === skill);
}
